#!/bin/sh
set -eu
umask 077
python3 -I -B - <<'INSTALL_APP_STAGE1_R29'
import base64,hashlib,os,platform,zlib
from pathlib import Path
assert os.geteuid()==0 and platform.system()=='Linux'
raw=zlib.decompress(base64.b64decode('',validate=True))
assert len(raw)==8870 and hashlib.sha256(raw).hexdigest()=='570a24e80ba8d97e2bf704d88710c9319582baaad6736903153091a822d37fc2'
p=Path('/root/t44-r9/app-stage1-r29-01.py');assert p.parent.resolve()==p.parent
fd=os.open(p,os.O_WRONLY|os.O_CREAT|os.O_EXCL|os.O_NOFOLLOW,0o444)
with os.fdopen(fd,'wb') as f:f.write(raw);f.flush();os.fsync(f.fileno())
print('R29_APP_STAGE1_WRAPPER_INSTALLED_ONLY')
INSTALL_APP_STAGE1_R29
